        let type = null;
    if(data != null){
        colorLog('\t\\_data: ', {c:Color.Cyan})
        colorLog('\t\t'+data, {c:Color.Yellow})
    }
    if(action != null){
        colorLog('\t\\_action: ', {c:Color.Cyan})
