function countElements(arr) {
  var counts = {};
  // Iterate over the array elements
  for (var i = 0; i < arr.length; i++) {
    var element = arr[i];

    // Check if the element is already a key in the counts object
    if (counts[element]) {
      // Increment the count for the element
      counts[element]++;
